import{_ as s,o as a,c as i,a0 as t}from"./chunks/framework.OED5XGjC.js";const k=JSON.parse(`{"title":"Flow: a task's life in the ledger","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/flow.md","filePath":"explanation/flow.md"}`),n={name:"explanation/flow.md"};function h(o,e,d,l,p,r){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="flow-a-task-s-life-in-the-ledger" tabindex="-1">Flow: a task&#39;s life in the ledger <a class="header-anchor" href="#flow-a-task-s-life-in-the-ledger" aria-label="Permalink to &quot;Flow: a task&#39;s life in the ledger&quot;">​</a></h1><p>One end-to-end narrative — what actually happens on disk and in git when a piece of work goes from &quot;someone said so&quot; to &quot;done&quot;. Every hop is a verb; nothing hand-edits <code>project/</code>.</p><h2 id="_1-capture" tabindex="-1">1. Capture <a class="header-anchor" href="#_1-capture" aria-label="Permalink to &quot;1. Capture&quot;">​</a></h2><p>A human says &quot;we should ship the thing.&quot; The agent offers to record it; on a yes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> todo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ship the thing&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → added T-001 open pri:high #release ship the thing</span></span></code></pre></div><p>Under the hood: <code>meta.toml</code>&#39;s <code>[next] t</code> counter allocates <code>T-001</code>, one line lands in <code>project/TODO.md</code>, and the whole thing commits as <code>chore: add T-001</code> on the orphan <code>project</code> branch. Your code branch never sees it.</p><h2 id="_2-orient" tabindex="-1">2. Orient <a class="header-anchor" href="#_2-orient" aria-label="Permalink to &quot;2. Orient&quot;">​</a></h2><p>Next session, anyone — human or agent — asks &quot;what&#39;s on the board?&quot;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prompt</span></span></code></pre></div><p>The index (redb snapshot, rebuilt lazily if stale) answers without re-parsing markdown: counts by kind, what&#39;s claimed, what&#39;s open — sized for a context window. <code>myco view board</code> gives the five-lane kanban; <code>myco ui</code> gives the interactive version.</p><h2 id="_3-claim-and-work" tabindex="-1">3. Claim and work <a class="header-anchor" href="#_3-claim-and-work" aria-label="Permalink to &quot;3. Claim and work&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claimed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in-progress</span></span></code></pre></div><p>Each is one legal state-machine step and one commit. <code>owner:devin</code> is a namespaced actor string — several agents can share one ledger without stepping on each other. Deps are data too: <code>--blocks I-003</code> records that this task blocks an issue; <code>resume</code> surfaces them.</p><h2 id="_4-hand-off" tabindex="-1">4. Hand off <a class="header-anchor" href="#_4-hand-off" aria-label="Permalink to &quot;4. Hand off&quot;">​</a></h2><p>The session ends mid-work:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> handoff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --actor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli:abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --note</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Done: draft. Next: screenshots. Open: hero copy.&quot;</span></span></code></pre></div><p>An append-only <code>##</code> entry lands in <code>handoffs/T-001.md</code>, one commit. Nothing is lost; nothing is rewritten.</p><h2 id="_5-resume" tabindex="-1">5. Resume <a class="header-anchor" href="#_5-resume" aria-label="Permalink to &quot;5. Resume&quot;">​</a></h2><p>A week later, a fresh session:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span></span></code></pre></div><p>Prints the item, its <code>blocks:</code> titles, the latest handoff entries, and the open <code>- [ ]</code> checklist — the minimal restart context. If the session had <em>died</em> rather than ended, <code>myco interrupt --session cli:abc123</code> would have walked claimed items back to <code>open</code> with an <code>interrupted</code> marker instead.</p><h2 id="_6-done" tabindex="-1">6. Done <a class="header-anchor" href="#_6-done" aria-label="Permalink to &quot;6. Done&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> todo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-001</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The line (subtree included) moves from <code>TODO.md</code> to <code>DONE.md</code> with a write-once <code>done:</code> stamp — completed work stays browsable via <code>myco done list</code> instead of vanishing. <code>check</code> validates file spec, state machine, and index drift; every step above was already a commit on <code>project</code>, so <code>git -C project log</code> replays the item&#39;s whole life.</p><h2 id="the-shape-underneath" tabindex="-1">The shape underneath <a class="header-anchor" href="#the-shape-underneath" aria-label="Permalink to &quot;The shape underneath&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>intent ──► markdown (canonical) ──► index (derived) ──► views (reads)</span></span>
<span class="line"><span>                │                        ▲</span></span>
<span class="line"><span>                └── verbs ──► commit-per-mutation on \`project\` branch</span></span></code></pre></div><p>Capture is a write; orient/resume are reads over the disposable index; the audit trail is git itself. See <a href="./architecture.html">architecture</a> for the crates and <a href="./file-spec.html">the file spec</a> for the grammar each step produces.</p>`,27)])])}const g=s(n,[["render",h]]);export{k as __pageData,g as default};
